// Function Calling: the model emits a structured tool call, a dispatcher
// validates the arguments against the tool's JSON-schema-like definition,
// executes it, and feeds the result back for a final answer.

interface ParameterSchema {
  type: 'string' | 'number';
  description: string;
}

interface ToolSchema {
  name: string;
  description: string;
  parameters: Record<string, ParameterSchema>;
  required: string[];
}

interface ToolCall {
  name: string;
  arguments: Record<string, any>;
}

type ToolFn = (args: Record<string, any>) => string;

class ToolRegistry {
  private schemas = new Map<string, ToolSchema>();
  private impls = new Map<string, ToolFn>();

  register(schema: ToolSchema, impl: ToolFn): void {
    this.schemas.set(schema.name, schema);
    this.impls.set(schema.name, impl);
  }

  // Validate the emitted call against the schema, then execute it.
  dispatch(call: ToolCall): string {
    const schema = this.schemas.get(call.name);
    if (!schema) return `Error: unknown tool "${call.name}"`;

    for (const key of schema.required) {
      if (!(key in call.arguments)) {
        return `Error: missing required argument "${key}" for ${call.name}`;
      }
    }
    for (const [key, spec] of Object.entries(schema.parameters)) {
      if (key in call.arguments && typeof call.arguments[key] !== spec.type) {
        return `Error: argument "${key}" must be ${spec.type}`;
      }
    }
    return this.impls.get(call.name)!(call.arguments);
  }
}

// Model stub: chooses a tool + arguments from the user query (no regex).
function modelDecide(query: string): ToolCall | null {
  const q = query.toLowerCase();
  if (q.includes('weather')) {
    const marker = ' in ';
    const at = q.indexOf(marker);
    let city = 'unknown';
    if (at >= 0) {
      city = query.slice(at + marker.length).replace('?', '').trim().split(' ')[0];
    }
    return { name: 'get_weather', arguments: { city } };
  }
  if (q.includes('+') || q.includes('compute') || q.includes('plus')) {
    const expression = query.split('').filter(ch => '0123456789+*'.includes(ch)).join('');
    return { name: 'calculator', arguments: { expression } };
  }
  return null;
}

// Tiny safe evaluator for sums of products, e.g. "2*3+4".
function calc(expr: string): number {
  return expr.split('+').reduce((sum, term) => {
    if (!term) return sum;
    return sum + term.split('*').reduce((p, n) => p * Number(n), 1);
  }, 0);
}

function main() {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'get_weather',
      description: 'Current weather for a city',
      parameters: { city: { type: 'string', description: 'city name' } },
      required: ['city'],
    },
    args => `Weather in ${args.city}: 72F, partly cloudy`,
  );
  registry.register(
    {
      name: 'calculator',
      description: 'Evaluate an arithmetic expression',
      parameters: { expression: { type: 'string', description: 'expression' } },
      required: ['expression'],
    },
    args => `${args.expression} = ${calc(String(args.expression))}`,
  );

  const queries = ['What is the weather in Paris?', 'Compute 3+4+5', 'Tell me a story'];
  for (const query of queries) {
    console.log(`\nUser: ${query}`);
    const call = modelDecide(query);
    if (!call) {
      console.log('Model: (no tool needed) answering directly.');
      continue;
    }
    console.log(`Model -> tool_call ${call.name}(${JSON.stringify(call.arguments)})`);
    const result = registry.dispatch(call);
    console.log(`Tool result: ${result}`);
    console.log(`Model -> final answer: ${result}`);
  }
}

main();

