#!/usr/bin/env python3

from dataclasses import dataclass
from typing import Any, Callable, Dict, List, Optional

@dataclass
class ToolSchema:
    name: str
    description: str
    parameters: Dict[str, Dict[str, str]]
    required: List[str]

@dataclass
class ToolCall:
    name: str
    arguments: Dict[str, Any]

class ToolRegistry:
    def __init__(self):
        self.schemas: Dict[str, ToolSchema] = {}
        self.impls: Dict[str, Callable[[Dict[str, Any]], str]] = {}

    def register(self, schema: ToolSchema, impl: Callable[[Dict[str, Any]], str]) -> None:
        self.schemas[schema.name] = schema
        self.impls[schema.name] = impl

    # Validate the emitted call against the schema, then execute it.
    def dispatch(self, call: ToolCall) -> str:
        schema = self.schemas.get(call.name)
        if schema is None:
            return f'Error: unknown tool "{call.name}"'
        for key in schema.required:
            if key not in call.arguments:
                return f'Error: missing required argument "{key}" for {call.name}'
        for key, spec in schema.parameters.items():
            if key in call.arguments and spec["type"] == "string" and not isinstance(call.arguments[key], str):
                return f'Error: argument "{key}" must be string'
        return self.impls[call.name](call.arguments)

# Model stub: chooses a tool + arguments from the user query.
def model_decide(query: str) -> Optional[ToolCall]:
    q = query.lower()
    if "weather" in q:
        city = "unknown"
        if " in " in q:
            tail = query[q.index(" in ") + 4:]
            city = tail.replace("?", "").strip().split(" ")[0]
        return ToolCall("get_weather", {"city": city})
    if "+" in q or "compute" in q or "plus" in q:
        expression = "".join(ch for ch in query if ch in "0123456789+*")
        return ToolCall("calculator", {"expression": expression})
    return None

# Tiny safe evaluator for sums of products, e.g. "2*3+4".
def calc(expr: str) -> int:
    total = 0
    for term in expr.split("+"):
        if not term:
            continue
        product = 1
        for n in term.split("*"):
            product *= int(n)
        total += product
    return total

def main():
    registry = ToolRegistry()
    registry.register(
        ToolSchema("get_weather", "Current weather for a city",
                   {"city": {"type": "string", "description": "city name"}}, ["city"]),
        lambda args: f'Weather in {args["city"]}: 72F, partly cloudy',
    )
    registry.register(
        ToolSchema("calculator", "Evaluate an arithmetic expression",
                   {"expression": {"type": "string", "description": "expression"}}, ["expression"]),
        lambda args: f'{args["expression"]} = {calc(args["expression"])}',
    )

    queries = ["What is the weather in Paris?", "Compute 3+4+5", "Tell me a story"]
    for query in queries:
        print(f"\nUser: {query}")
        call = model_decide(query)
        if call is None:
            print("Model: (no tool needed) answering directly.")
            continue
        print(f"Model -> tool_call {call.name}({call.arguments})")
        result = registry.dispatch(call)
        print(f"Tool result: {result}")
        print(f"Model -> final answer: {result}")

if __name__ == "__main__":
    main()

code.rust:
use std::collections::HashMap;

#[derive(Clone)]
struct ToolSchema {
    name: String,
    description: String,
    param_types: HashMap<String, String>,
    required: Vec<String>,
}

struct ToolCall {
    name: String,
    arguments: HashMap<String, String>,
}

struct ToolRegistry {
    schemas: HashMap<String, ToolSchema>,
    impls: HashMap<String, fn(&HashMap<String, String>) -> String>,
}

impl ToolRegistry {
    fn new() -> Self {
        Self { schemas: HashMap::new(), impls: HashMap::new() }
    }

    fn register(&mut self, schema: ToolSchema, imp: fn(&HashMap<String, String>) -> String) {
        self.impls.insert(schema.name.clone(), imp);
        self.schemas.insert(schema.name.clone(), schema);
    }

    // Validate the emitted call against the schema, then execute it.
    fn dispatch(&self, call: &ToolCall) -> String {
        let schema = match self.schemas.get(&call.name) {
            Some(s) => s,
            None => return format!("Error: unknown tool [{}]", call.name),
        };
        for key in &schema.required {
            if !call.arguments.contains_key(key) {
                return format!("Error: missing required argument [{}] for {}", key, call.name);
            }
        }
        let _ = &schema.param_types;
        let _ = &schema.description;
        (self.impls.get(&call.name).unwrap())(&call.arguments)
    }
}

fn one(key: &str, value: &str) -> HashMap<String, String> {
    let mut m = HashMap::new();
    m.insert(key.to_string(), value.to_string());
    m
}

// Model stub: chooses a tool + arguments from the user query.
fn model_decide(query: &str) -> Option<ToolCall> {
    let q = query.to_lowercase();
    if q.contains("weather") {
        let mut city = String::from("unknown");
        if let Some(pos) = q.find(" in ") {
            let tail = &query[pos + 4..];
            city = tail.replace("?", "").trim().split(' ').next().unwrap_or("unknown").to_string();
        }
        return Some(ToolCall { name: "get_weather".to_string(), arguments: one("city", &city) });
    }
    if q.contains('+') || q.contains("compute") || q.contains("plus") {
        let expr: String = query.chars().filter(|c| "0123456789+*".contains(*c)).collect();
        return Some(ToolCall { name: "calculator".to_string(), arguments: one("expression", &expr) });
    }
    None
}

// Tiny safe evaluator for sums of products, e.g. "2*3+4".
fn calc(expr: &str) -> i64 {
    let mut total: i64 = 0;
    for term in expr.split('+') {
        if term.is_empty() {
            continue;
        }
        let mut product: i64 = 1;
        for n in term.split('*') {
            product *= n.parse::<i64>().unwrap_or(0);
        }
        total += product;
    }
    total
}

fn main() {
    let mut registry = ToolRegistry::new();
    registry.register(
        ToolSchema {
            name: "get_weather".to_string(),
            description: "Current weather for a city".to_string(),
            param_types: one("city", "string"),
            required: vec!["city".to_string()],
        },
        |args| format!("Weather in {}: 72F, partly cloudy", args.get("city").unwrap()),
    );
    registry.register(
        ToolSchema {
            name: "calculator".to_string(),
            description: "Evaluate an arithmetic expression".to_string(),
            param_types: one("expression", "string"),
            required: vec!["expression".to_string()],
        },
        |args| {
            let expr = args.get("expression").unwrap();
            format!("{} = {}", expr, calc(expr))
        },
    );

    let queries = vec!["What is the weather in Paris?", "Compute 3+4+5", "Tell me a story"];
    for query in queries {
        println!("\nUser: {}", query);
        match model_decide(query) {
            None => println!("Model: (no tool needed) answering directly."),
            Some(call) => {
                println!("Model -> tool_call {}({:?})", call.name, call.arguments);
                let result = registry.dispatch(&call);
                println!("Tool result: {}", result);
                println!("Model -> final answer: {}", result);
            }
        }
    }
}

code.typescript:
// Code Execution: the model emits a program as a small typed expression tree,
// not a raw string. A validator runs an allow-list security scan plus a size
// check, then a sandbox interprets the tree under CPU (step) and memory (node)
// limits. Three requests show a clean run, a blocked syscall, and a runaway loop.

type Node =
  | { kind: 'mean'; values: number[] }
  | { kind: 'variance'; values: number[] }
  | { kind: 'scale'; factor: number; of: Node }
  | { kind: 'repeat'; times: number; of: Node }
  | { kind: 'syscall'; name: string };

const ALLOWED = ['mean', 'variance', 'scale', 'repeat'];
const MAX_NODES = 32; // memory proxy
const STEP_BUDGET = 200; // cpu proxy

function countNodes(node: Node): number {
  if (node.kind === 'scale' || node.kind === 'repeat') return 1 + countNodes(node.of);
  return 1;
}

// Security + resource validation, run before anything executes.
function validate(node: Node): string | null {
  let bad: string | null = null;
  const walk = (n: Node): void => {
    if (!ALLOWED.includes(n.kind)) {
      bad = n.kind === 'syscall' ? `blocked call "${n.name}"` : `disallowed op "${n.kind}"`;
    }
    if (n.kind === 'scale' || n.kind === 'repeat') walk(n.of);
  };
  walk(node);
  if (bad) return bad;
  const nodes = countNodes(node);
  if (nodes > MAX_NODES) return `program too large (${nodes} > ${MAX_NODES} nodes)`;
  return null;
}

function mean(xs: number[]): number {
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}
function variance(xs: number[]): number {
  const m = mean(xs);
  return mean(xs.map(x => (x - m) * (x - m)));
}

// Sandboxed interpreter. Each visit spends one CPU step; over budget it aborts.
function run(node: Node, budget: { steps: number }): number {
  budget.steps -= 1;
  if (budget.steps < 0) throw new Error('resource limit: step budget exceeded');
  if (node.kind === 'mean') return mean(node.values);
  if (node.kind === 'variance') return variance(node.values);
  if (node.kind === 'scale') return node.factor * run(node.of, budget);
  if (node.kind === 'repeat') {
    let last = 0;
    for (let i = 0; i < node.times; i++) last = run(node.of, budget);
    return last;
  }
  throw new Error('unreachable: unvalidated op reached the sandbox');
}

function describe(n: Node): string {
  if (n.kind === 'mean') return `mean(${n.values.length} vals)`;
  if (n.kind === 'variance') return `variance([${n.values.join(', ')}])`;
  if (n.kind === 'scale') return `scale(${n.factor}, ${describe(n.of)})`;
  if (n.kind === 'repeat') return `repeat(${n.times}, ${describe(n.of)})`;
  return `syscall("${n.name}")`;
}

function execute(label: string, program: Node): void {
  console.log(`\nRequest: ${label}`);
  console.log(`  generated: ${describe(program)}`);
  const nodes = countNodes(program);
  console.log(`  validate: nodes ${nodes}/${MAX_NODES}, network blocked, allow-list [${ALLOWED.join(', ')}]`);
  const problem = validate(program);
  if (problem) {
    console.log(`  rejected before execution: ${problem}`);
    console.log('  audit: attempt logged, sandbox never entered');
    return;
  }
  const budget = { steps: STEP_BUDGET };
  try {
    const out = run(program, budget);
    console.log(`  execute: ok, steps used ${STEP_BUDGET - budget.steps}/${STEP_BUDGET}`);
    console.log(`  output: ${out.toFixed(6)}`);
  } catch (err) {
    console.log(`  execute: aborted after ${STEP_BUDGET - budget.steps}/${STEP_BUDGET} steps`);
    console.log(`  reason: ${(err as Error).message}`);
  }
  console.log('  cleanup: temp workspace removed, attempt logged');
}

function main() {
  console.log('=== Code Execution Sandbox ===');
  console.log(`limits: cpu ${STEP_BUDGET} steps, memory ${MAX_NODES} nodes, network blocked`);
  const returns = [0.12, 0.08, 0.15];

  execute('average daily return across 3 stocks', { kind: 'mean', values: returns });
  execute('portfolio variance for 3 stocks', {
    kind: 'scale',
    factor: 100,
    of: { kind: 'variance', values: returns },
  });
  execute('read deployment secrets from the host', {
    kind: 'scale',
    factor: 2,
    of: { kind: 'syscall', name: 'read_env_secrets' },
  });
  execute('recompute variance in a 5000-iteration loop', {
    kind: 'repeat',
    times: 5000,
    of: { kind: 'variance', values: returns },
  });

  console.log('\nsummary: 2 executed, 1 blocked by the security scan, 1 stopped by the resource limit');
}

main();

code.python:
#!/usr/bin/env python3
# Code Execution: the model emits a program as a small typed expression tree,
# not a raw string. A validator runs an allow-list security scan plus a size
# check, then a sandbox interprets the tree under CPU (step) and memory (node)
# limits. Three requests show a clean run, a blocked syscall, and a runaway loop.

from dataclasses import dataclass
from typing import List, Optional, Union

@dataclass
class Mean:
    values: List[float]

@dataclass
class Variance:
    values: List[float]

@dataclass
class Scale:
    factor: float
    of: "Node"

@dataclass
class Repeat:
    times: int
    of: "Node"

@dataclass
class Syscall:
    name: str

Node = Union[Mean, Variance, Scale, Repeat, Syscall]

ALLOWED = {"mean", "variance", "scale", "repeat"}
MAX_NODES = 32     # memory proxy
STEP_BUDGET = 200  # cpu proxy

@dataclass
class Budget:
    steps: int

def kind(n: Node) -> str:
    return type(n).__name__.lower()

def count_nodes(n: Node) -> int:
    if isinstance(n, (Scale, Repeat)):
        return 1 + count_nodes(n.of)
    return 1

# Security + resource validation, run before anything executes.
def validate(n: Node) -> Optional[str]:
    bad: Optional[str] = None

    def walk(node: Node) -> None:
        nonlocal bad
        if kind(node) not in ALLOWED:
            bad = f'blocked call "{node.name}"' if isinstance(node, Syscall) else f'disallowed op "{kind(node)}"'
        if isinstance(node, (Scale, Repeat)):
            walk(node.of)

    walk(n)
    if bad:
        return bad
    nodes = count_nodes(n)
    if nodes > MAX_NODES:
        return f"program too large ({nodes} > {MAX_NODES} nodes)"
    return None

def mean(xs: List[float]) -> float:
    return sum(xs) / len(xs)

def variance(xs: List[float]) -> float:
    m = mean(xs)
    return mean([(x - m) * (x - m) for x in xs])

# Sandboxed interpreter. Each visit spends one CPU step; over budget it aborts.
def run(n: Node, budget: Budget) -> float:
    budget.steps -= 1
    if budget.steps < 0:
        raise RuntimeError("resource limit: step budget exceeded")
    if isinstance(n, Mean):
        return mean(n.values)
    if isinstance(n, Variance):
        return variance(n.values)
    if isinstance(n, Scale):
        return n.factor * run(n.of, budget)
    if isinstance(n, Repeat):
        last = 0.0
        for _ in range(n.times):
            last = run(n.of, budget)
        return last
    raise RuntimeError("unreachable: unvalidated op reached the sandbox")

def describe(n: Node) -> str:
    if isinstance(n, Mean):
        return f"mean({len(n.values)} vals)"
    if isinstance(n, Variance):
        return "variance([" + ", ".join(str(v) for v in n.values) + "])"
    if isinstance(n, Scale):
        return f"scale({n.factor}, {describe(n.of)})"
    if isinstance(n, Repeat):
        return f"repeat({n.times}, {describe(n.of)})"
    return f'syscall("{n.name}")'

def execute(label: str, program: Node) -> None:
    print(f"\nRequest: {label}")
    print(f"  generated: {describe(program)}")
    nodes = count_nodes(program)
    print(f"  validate: nodes {nodes}/{MAX_NODES}, network blocked, allow-list {sorted(ALLOWED)}")
    problem = validate(program)
    if problem:
        print(f"  rejected before execution: {problem}")
        print("  audit: attempt logged, sandbox never entered")
        return
    budget = Budget(STEP_BUDGET)
    try:
        out = run(program, budget)
        print(f"  execute: ok, steps used {STEP_BUDGET - budget.steps}/{STEP_BUDGET}")
        print(f"  output: {out:.6f}")
    except RuntimeError as err:
        print(f"  execute: aborted after {STEP_BUDGET - budget.steps}/{STEP_BUDGET} steps")
        print(f"  reason: {err}")
    print("  cleanup: temp workspace removed, attempt logged")

def main() -> None:
    print("=== Code Execution Sandbox ===")
    print(f"limits: cpu {STEP_BUDGET} steps, memory {MAX_NODES} nodes, network blocked")
    returns = [0.12, 0.08, 0.15]

    execute("average daily return across 3 stocks", Mean(returns))
    execute("portfolio variance for 3 stocks", Scale(100, Variance(returns)))
    execute("read deployment secrets from the host", Scale(2, Syscall("read_env_secrets")))
    execute("recompute variance in a 5000-iteration loop", Repeat(5000, Variance(returns)))

    print("\nsummary: 2 executed, 1 blocked by the security scan, 1 stopped by the resource limit")

if __name__ == "__main__":
    main()

code.rust:
// Code Execution: the model emits a program as a small typed expression tree,
// not a raw string. A validator runs an allow-list security scan plus a size
// check, then a sandbox interprets the tree under CPU (step) and memory (node)
// limits. Three requests show a clean run, a blocked syscall, and a runaway loop.

const MAX_NODES: usize = 32; // memory proxy
const STEP_BUDGET: i64 = 200; // cpu proxy

enum Node {
    Mean(Vec<f64>),
    Variance(Vec<f64>),
    Scale(f64, Box<Node>),
    Repeat(usize, Box<Node>),
    Syscall(String),
}

fn kind(n: &Node) -> &'static str {
    match n {
        Node::Mean(_) => "mean",
        Node::Variance(_) => "variance",
        Node::Scale(_, _) => "scale",
        Node::Repeat(_, _) => "repeat",
        Node::Syscall(_) => "syscall",
    }
}

fn is_allowed(n: &Node) -> bool {
    !matches!(n, Node::Syscall(_))
}

fn count_nodes(n: &Node) -> usize {
    match n {
        Node::Scale(_, of) | Node::Repeat(_, of) => 1 + count_nodes(of),
        _ => 1,
    }
}

// Security + resource validation, run before anything executes.
fn validate(n: &Node) -> Option<String> {
    fn walk(n: &Node, bad: &mut Option<String>) {
        if !is_allowed(n) {
            if let Node::Syscall(name) = n {
                *bad = Some(format!("blocked call \"{}\"", name));
            }
        }
        match n {
            Node::Scale(_, of) | Node::Repeat(_, of) => walk(of, bad),
            _ => {}
        }
    }
    let mut bad: Option<String> = None;
    walk(n, &mut bad);
    if bad.is_some() {
        return bad;
    }
    let nodes = count_nodes(n);
    if nodes > MAX_NODES {
        return Some(format!("program too large ({} > {} nodes)", nodes, MAX_NODES));
    }
    None
}

fn mean(xs: &[f64]) -> f64 {
    xs.iter().sum::<f64>() / xs.len() as f64
}

fn variance(xs: &[f64]) -> f64 {
    let m = mean(xs);
    mean(&xs.iter().map(|x| (x - m) * (x - m)).collect::<Vec<f64>>())
}

// Sandboxed interpreter. Each visit spends one CPU step; over budget it aborts.
fn run(n: &Node, steps: &mut i64) -> Result<f64, String> {
    *steps -= 1;
    if *steps < 0 {
        return Err("resource limit: step budget exceeded".to_string());
    }
    match n {
        Node::Mean(v) => Ok(mean(v)),
        Node::Variance(v) => Ok(variance(v)),
        Node::Scale(factor, of) => Ok(factor * run(of, steps)?),
        Node::Repeat(times, of) => {
            let mut last = 0.0;
            for _ in 0..*times {
                last = run(of, steps)?;
            }
            Ok(last)
        }
        Node::Syscall(_) => Err("unreachable: unvalidated op reached the sandbox".to_string()),
    }
}

fn describe(n: &Node) -> String {
    match n {
        Node::Mean(v) => format!("mean({} vals)", v.len()),
        Node::Variance(v) => {
            let items: Vec<String> = v.iter().map(|x| x.to_string()).collect();
            format!("variance([{}])", items.join(", "))
        }
        Node::Scale(factor, of) => format!("scale({}, {})", factor, describe(of)),
        Node::Repeat(times, of) => format!("repeat({}, {})", times, describe(of)),
        Node::Syscall(name) => format!("syscall(\"{}\")", name),
    }
}

fn execute(label: &str, program: &Node) {
    println!("\nRequest: {}", label);
    println!("  generated: {}", describe(program));
    let nodes = count_nodes(program);
    println!(
        "  validate: nodes {}/{}, network blocked, allow-list [mean, repeat, scale, variance]",
        nodes, MAX_NODES
    );
    let _ = kind(program);
    if let Some(problem) = validate(program) {
        println!("  rejected before execution: {}", problem);
        println!("  audit: attempt logged, sandbox never entered");
        return;
    }
    let mut steps = STEP_BUDGET;
    match run(program, &mut steps) {
        Ok(out) => {
            println!("  execute: ok, steps used {}/{}", STEP_BUDGET - steps, STEP_BUDGET);
            println!("  output: {:.6}", out);
        }
        Err(reason) => {
            println!("  execute: aborted after {}/{} steps", STEP_BUDGET - steps, STEP_BUDGET);
            println!("  reason: {}", reason);
        }
    }
    println!("  cleanup: temp workspace removed, attempt logged");
}

fn main() {
    println!("=== Code Execution Sandbox ===");
    println!("limits: cpu {} steps, memory {} nodes, network blocked", STEP_BUDGET, MAX_NODES);
    let returns = vec![0.12, 0.08, 0.15];

    execute("average daily return across 3 stocks", &Node::Mean(returns.clone()));
    execute(
        "portfolio variance for 3 stocks",
        &Node::Scale(100.0, Box::new(Node::Variance(returns.clone()))),
    );
    execute(
        "read deployment secrets from the host",
        &Node::Scale(2.0, Box::new(Node::Syscall("read_env_secrets".to_string()))),
    );
    execute(
        "recompute variance in a 5000-iteration loop",
        &Node::Repeat(5000, Box::new(Node::Variance(returns.clone()))),
    );

    println!("\nsummary: 2 executed, 1 blocked by the security scan, 1 stopped by the resource limit");
}

