use std::collections::HashMap;

// Params carried by a request: string args plus a couple of numeric args,
// kept simple so the example stays dependency-free.
#[derive(Default, Clone)]
struct Params {
    name: String,
    uri: String,
    a: f64,
    b: f64,
    city: String,
}

struct Request {
    id: u32,
    method: String,
    params: Params,
}

struct Response {
    id: u32,
    result: String,
    error: Option<String>,
}

struct ToolDef {
    name: String,
    description: String,
    schema: Vec<String>,
    handler: fn(&Params) -> String,
}

struct ResourceDef {
    uri: String,
    name: String,
    read: fn() -> String,
}

// Channel abstraction: in a real deployment this is stdio or a socket.
struct McpServer {
    tools: Vec<ToolDef>,
    resources: Vec<ResourceDef>,
}

impl McpServer {
    fn new() -> Self {
        Self { tools: Vec::new(), resources: Vec::new() }
    }

    fn register_tool(&mut self, tool: ToolDef) {
        self.tools.push(tool);
    }

    fn register_resource(&mut self, res: ResourceDef) {
        self.resources.push(res);
    }

    fn handle(&self, req: &Request) -> Response {
        match req.method.as_str() {
            "tools/list" => {
                let listing: Vec<String> = self.tools.iter()
                    .map(|t| format!("{}({}) - {}", t.name, t.schema.join(", "), t.description))
                    .collect();
                Response { id: req.id, result: listing.join("\n"), error: None }
            }
            "tools/call" => {
                match self.tools.iter().find(|t| t.name == req.params.name) {
                    Some(t) => Response { id: req.id, result: (t.handler)(&req.params), error: None },
                    None => Response { id: req.id, result: String::new(),
                        error: Some(format!("No such tool: {}", req.params.name)) },
                }
            }
            "resources/list" => {
                let listing: Vec<String> = self.resources.iter()
                    .map(|r| format!("{} ({})", r.uri, r.name))
                    .collect();
                Response { id: req.id, result: listing.join("\n"), error: None }
            }
            "resources/read" => {
                match self.resources.iter().find(|r| r.uri == req.params.uri) {
                    Some(r) => Response { id: req.id, result: (r.read)(), error: None },
                    None => Response { id: req.id, result: String::new(),
                        error: Some(format!("No such resource: {}", req.params.uri)) },
                }
            }
            other => Response { id: req.id, result: String::new(),
                error: Some(format!("Unknown method: {}", other)) },
        }
    }
}

struct McpClient<'a> {
    server: &'a McpServer,
    seq: u32,
}

impl<'a> McpClient<'a> {
    fn new(server: &'a McpServer) -> Self {
        Self { server, seq: 0 }
    }

    fn call(&mut self, method: &str, params: Params) -> Result<String, String> {
        self.seq += 1;
        let req = Request { id: self.seq, method: method.to_string(), params };
        let res = self.server.handle(&req);
        match res.error {
            Some(e) => Err(e),
            None => Ok(res.result),
        }
    }
}

fn main() {
    let mut server = McpServer::new();
    server.register_tool(ToolDef {
        name: "add".to_string(),
        description: "Add two integers".to_string(),
        schema: vec!["a".to_string(), "b".to_string()],
        handler: |p| format!("{}", p.a + p.b),
    });
    server.register_tool(ToolDef {
        name: "get_weather".to_string(),
        description: "Return canned weather for a city".to_string(),
        schema: vec!["city".to_string()],
        handler: |p| format!("{{ city: {}, tempC: 21, sky: clear }}", p.city),
    });
    server.register_resource(ResourceDef {
        uri: "file:///readme.txt".to_string(),
        name: "Project README".to_string(),
        read: || "This project demonstrates the Model Context Protocol.".to_string(),
    });

    let _unused: HashMap<String, String> = HashMap::new();
    let mut client = McpClient::new(&server);

    println!("Discovered tools:");
    println!("{}", client.call("tools/list", Params::default()).unwrap());

    println!("\nInvoking tools:");
    let add_args = Params { name: "add".to_string(), a: 2.0, b: 40.0, ..Default::default() };
    println!("  add(2, 40) = {}", client.call("tools/call", add_args).unwrap());
    let wx_args = Params { name: "get_weather".to_string(), city: "Paris".to_string(), ..Default::default() };
    println!("  get_weather(Paris) = {}", client.call("tools/call", wx_args).unwrap());

    println!("\nResources:");
    println!("{}", client.call("resources/list", Params::default()).unwrap());
    let read_args = Params { uri: "file:///readme.txt".to_string(), ..Default::default() };
    println!("  read = \"{}\"", client.call("resources/read", read_args).unwrap());

    println!("\nError handling:");
    let bad = Params { name: "divide".to_string(), ..Default::default() };
    match client.call("tools/call", bad) {
        Ok(_) => {}
        Err(e) => println!("  {}", e),
    }
}

code.typescript:
// Control Plane as a Tool: the agent only ever calls one stable tool, execute(task).
// An internal control plane classifies the request, routes it to the right backend
// services, enforces auth scope and a quota, aggregates results, and logs every call.
// Backends can be swapped behind the interface without changing what the agent calls.

interface Backend {
  name: string;
  scope: string;
  cost: number;
  run: (task: string, ctx: Record<string, string>) => string;
}

interface Caller {
  id: string;
  scopes: string[];
  quota: number;
}

interface LogEntry {
  request: number;
  backend: string;
  decision: string;
}

// The control plane: single interface in front of a registry of backends.
class ControlPlane {
  private registry: Backend[] = [];
  private log: LogEntry[] = [];
  private counter = 0;

  register(backend: Backend): void {
    // Swapping a backend of the same name replaces it; the agent interface is unchanged.
    this.registry = this.registry.filter(b => b.name !== backend.name).concat(backend);
    this.registry.sort((a, b) => order(a.name) - order(b.name));
  }

  private classify(task: string): string[] {
    const q = task.toLowerCase();
    const plan: string[] = [];
    if (q.includes('revenue') || q.includes('metric') || q.includes('fetch')) plan.push('metrics.fetch');
    if (q.includes('summar')) plan.push('text.summarize');
    if (q.includes('translat') || q.includes('french')) plan.push('lang.translate');
    if (q.includes('chart') || q.includes('render') || q.includes('plot')) plan.push('chart.render');
    return plan;
  }

  // The single tool the agent calls. Everything else is internal.
  execute(caller: Caller, task: string): string {
    this.counter += 1;
    const plan = this.classify(task);
    console.log(`Agent -> execute("${task}")`);
    console.log(`  [classify] route -> ${plan.join(', ') || '(none)'}`);
    const outputs: Record<string, string> = {};
    for (const name of plan) {
      const backend = this.registry.find(b => b.name === name)!;
      if (!caller.scopes.includes(backend.scope)) {
        console.log(`  [policy] ${name}: scope ${backend.scope} MISSING -> DENY`);
        this.log.push({ request: this.counter, backend: name, decision: 'deny-scope' });
        continue;
      }
      if (backend.cost > caller.quota) {
        console.log(`  [policy] ${name}: cost ${backend.cost} > quota ${caller.quota} -> DENY (rate limit)`);
        this.log.push({ request: this.counter, backend: name, decision: 'deny-quota' });
        continue;
      }
      const before = caller.quota;
      caller.quota -= backend.cost;
      console.log(`  [policy] ${name}: scope ${backend.scope} OK, quota ${before}->${caller.quota} -> ALLOW`);
      outputs[name] = backend.run(task, outputs);
      console.log(`  [route]  ${name} -> ${outputs[name]}`);
      this.log.push({ request: this.counter, backend: name, decision: 'allow' });
    }
    const keys = Object.keys(outputs);
    const response = keys.length === 0
      ? 'request denied by policy, nothing executed'
      : keys.map(k => outputs[k]).join(' | ');
    console.log(`Agent <- ${response}\n`);
    return response;
  }

  dumpLog(): void {
    console.log('Audit log (one line per routed backend call):');
    for (const e of this.log) {
      console.log(`  req#${e.request} ${e.backend.padEnd(16)} ${e.decision}`);
    }
  }
}

function order(name: string): number {
  const seq = ['metrics.fetch', 'text.summarize', 'lang.translate', 'chart.render'];
  const i = seq.indexOf(name);
  return i < 0 ? 99 : i;
}

function main() {
  const plane = new ControlPlane();
  plane.register({ name: 'metrics.fetch', scope: 'metrics.read', cost: 2,
    run: () => 'Q3 revenue 1.42M, above Q2 at 1.30M' });
  plane.register({ name: 'text.summarize', scope: 'text.write', cost: 1,
    run: (_t, ctx) => `Summary: ${ctx['metrics.fetch'] ? 'revenue rose from Q2 to Q3' : 'no data'}` });
  plane.register({ name: 'lang.translate', scope: 'lang.write', cost: 1,
    run: () => 'Traduction (fr): le chiffre d affaires a progresse du T2 au T3' });
  plane.register({ name: 'chart.render', scope: 'chart.render', cost: 3,
    run: () => 'rendered revenue-bars.png' });

  const analyst: Caller = { id: 'analyst-bot', scopes: ['metrics.read', 'text.write', 'lang.write'], quota: 6 };
  console.log(`Caller ${analyst.id}, scopes [${analyst.scopes.join(', ')}], quota ${analyst.quota}\n`);

  plane.execute(analyst, 'Fetch the Q3 revenue and summarize it');
  plane.execute(analyst, 'Render a chart of it');

  console.log('(control plane swaps text.summarize for a v2 impl; agent interface unchanged)\n');
  plane.register({ name: 'text.summarize', scope: 'text.write', cost: 1,
    run: (_t, ctx) => `Summary v2: ${ctx['metrics.fetch'] ? 'Q3 beat Q2 on revenue' : 'no data'}` });

  plane.execute(analyst, 'Summarize the revenue again');
  plane.execute(analyst, 'Fetch this quarter metrics');

  plane.dumpLog();
}

main();

code.rust:
// Control Plane as a Tool: the agent only ever calls one stable tool, execute(task).
// An internal control plane classifies the request, routes it to the right backend
// services, enforces auth scope and a quota, aggregates results, and logs every call.
// Backends can be swapped behind the interface without changing what the agent calls.

use std::collections::HashMap;

struct Backend {
    name: String,
    scope: String,
    cost: i32,
    run: fn(&HashMap<String, String>) -> String,
}

struct Caller {
    id: String,
    scopes: Vec<String>,
    quota: i32,
}

const ORDER: [&str; 4] = ["metrics.fetch", "text.summarize", "lang.translate", "chart.render"];

fn order(name: &str) -> usize {
    ORDER.iter().position(|n| *n == name).unwrap_or(99)
}

struct ControlPlane {
    registry: Vec<Backend>,
    log: Vec<String>,
    counter: i32,
}

impl ControlPlane {
    fn new() -> Self {
        ControlPlane { registry: Vec::new(), log: Vec::new(), counter: 0 }
    }

    fn register(&mut self, backend: Backend) {
        // Swapping a backend of the same name replaces it; the agent interface is unchanged.
        self.registry.retain(|b| b.name != backend.name);
        self.registry.push(backend);
        self.registry.sort_by_key(|b| order(&b.name));
    }

    fn classify(&self, task: &str) -> Vec<String> {
        let q = task.to_lowercase();
        let mut plan: Vec<String> = Vec::new();
        if q.contains("revenue") || q.contains("metric") || q.contains("fetch") {
            plan.push("metrics.fetch".to_string());
        }
        if q.contains("summar") {
            plan.push("text.summarize".to_string());
        }
        if q.contains("translat") || q.contains("french") {
            plan.push("lang.translate".to_string());
        }
        if q.contains("chart") || q.contains("render") || q.contains("plot") {
            plan.push("chart.render".to_string());
        }
        plan
    }

    // The single tool the agent calls. Everything else is internal.
    fn execute(&mut self, caller: &mut Caller, task: &str) -> String {
        self.counter += 1;
        let plan = self.classify(task);
        println!("Agent -> execute(\"{}\")", task);
        let plan_text = if plan.is_empty() { "(none)".to_string() } else { plan.join(", ") };
        println!("  [classify] route -> {}", plan_text);
        let mut outputs: HashMap<String, String> = HashMap::new();
        let mut order_out: Vec<String> = Vec::new();
        for name in &plan {
            let backend = self.registry.iter().find(|b| &b.name == name).unwrap();
            if !caller.scopes.contains(&backend.scope) {
                println!("  [policy] {}: scope {} MISSING -> DENY", name, backend.scope);
                self.log.push(format!("req#{} {:<16} deny-scope", self.counter, name));
                continue;
            }
            if backend.cost > caller.quota {
                println!("  [policy] {}: cost {} > quota {} -> DENY (rate limit)", name, backend.cost, caller.quota);
                self.log.push(format!("req#{} {:<16} deny-quota", self.counter, name));
                continue;
            }
            let before = caller.quota;
            caller.quota -= backend.cost;
            println!("  [policy] {}: scope {} OK, quota {}->{} -> ALLOW", name, backend.scope, before, caller.quota);
            let out = (backend.run)(&outputs);
            println!("  [route]  {} -> {}", name, out);
            outputs.insert(name.clone(), out);
            order_out.push(name.clone());
            self.log.push(format!("req#{} {:<16} allow", self.counter, name));
        }
        let response = if order_out.is_empty() {
            "request denied by policy, nothing executed".to_string()
        } else {
            order_out.iter().map(|k| outputs[k].clone()).collect::<Vec<String>>().join(" | ")
        };
        println!("Agent <- {}\n", response);
        response
    }

    fn dump_log(&self) {
        println!("Audit log (one line per routed backend call):");
        for entry in &self.log {
            println!("  {}", entry);
        }
    }
}

fn metrics_fetch(_ctx: &HashMap<String, String>) -> String {
    "Q3 revenue 1.42M, above Q2 at 1.30M".to_string()
}
fn text_summarize(ctx: &HashMap<String, String>) -> String {
    let has = ctx.contains_key("metrics.fetch");
    format!("Summary: {}", if has { "revenue rose from Q2 to Q3" } else { "no data" })
}
fn text_summarize_v2(ctx: &HashMap<String, String>) -> String {
    let has = ctx.contains_key("metrics.fetch");
    format!("Summary v2: {}", if has { "Q3 beat Q2 on revenue" } else { "no data" })
}
fn lang_translate(_ctx: &HashMap<String, String>) -> String {
    "Traduction (fr): le chiffre d affaires a progresse du T2 au T3".to_string()
}
fn chart_render(_ctx: &HashMap<String, String>) -> String {
    "rendered revenue-bars.png".to_string()
}

fn main() {
    let mut plane = ControlPlane::new();
    plane.register(Backend { name: "metrics.fetch".to_string(), scope: "metrics.read".to_string(), cost: 2, run: metrics_fetch });
    plane.register(Backend { name: "text.summarize".to_string(), scope: "text.write".to_string(), cost: 1, run: text_summarize });
    plane.register(Backend { name: "lang.translate".to_string(), scope: "lang.write".to_string(), cost: 1, run: lang_translate });
    plane.register(Backend { name: "chart.render".to_string(), scope: "chart.render".to_string(), cost: 3, run: chart_render });

    let mut analyst = Caller {
        id: "analyst-bot".to_string(),
        scopes: vec!["metrics.read".to_string(), "text.write".to_string(), "lang.write".to_string()],
        quota: 6,
    };
    println!("Caller {}, scopes [{}], quota {}\n", analyst.id, analyst.scopes.join(", "), analyst.quota);

    plane.execute(&mut analyst, "Fetch the Q3 revenue and summarize it");
    plane.execute(&mut analyst, "Render a chart of it");

    println!("(control plane swaps text.summarize for a v2 impl; agent interface unchanged)\n");
    plane.register(Backend { name: "text.summarize".to_string(), scope: "text.write".to_string(), cost: 1, run: text_summarize_v2 });

    plane.execute(&mut analyst, "Summarize the revenue again");
    plane.execute(&mut analyst, "Fetch this quarter metrics");

    plane.dump_log();
}

