// Computer Use: an agent drives a GUI it can only perceive as screenshots.
// Each cycle it takes a screenshot (a text grid of labeled elements), grounds
// an intent to pixel coordinates, clicks, then observes whether the screen
// changed as expected, recovering from an unexpected consent popup.

interface Element {
  label: string;
  col: number;
  row: number;
}

interface Screenshot {
  screen: string;
  popup: boolean;
  elements: Element[];
}

// The simulated machine. The agent can only learn its state by screenshot.
class Desktop {
  screen = 'home';
  popupOpen = true;
  darkMode = false;

  screenshot(): Screenshot {
    if (this.popupOpen) {
      return { screen: this.screen, popup: true, elements: [
        { label: 'Consent: Accept', col: 1, row: 1 },
        { label: 'Consent: Decline', col: 2, row: 1 },
      ] };
    }
    if (this.screen === 'home') {
      return { screen: 'home', popup: false, elements: [
        { label: 'Settings', col: 0, row: 2 },
        { label: 'Profile', col: 2, row: 2 },
      ] };
    }
    if (this.screen === 'settings') {
      return { screen: 'settings', popup: false, elements: [
        { label: 'General', col: 0, row: 1 },
        { label: 'Appearance', col: 1, row: 1 },
      ] };
    }
    const label = this.darkMode ? 'Dark Mode: ON' : 'Dark Mode: OFF';
    return { screen: 'appearance', popup: false, elements: [{ label, col: 1, row: 1 }] };
  }

  // A click lands at pixel coords; the element nearest those pixels reacts.
  clickAt(x: number, y: number, shot: Screenshot): void {
    const hit = nearest(shot.elements, x, y);
    if (!hit) return;
    if (hit.label.startsWith('Consent:')) this.popupOpen = false;
    else if (hit.label === 'Settings') this.screen = 'settings';
    else if (hit.label === 'Appearance') this.screen = 'appearance';
    else if (hit.label.startsWith('Dark Mode')) this.darkMode = !this.darkMode;
  }
}

function px(el: Element): { x: number; y: number } {
  return { x: el.col * 100 + 50, y: el.row * 60 + 30 };
}

function nearest(els: Element[], x: number, y: number): Element | null {
  let best: Element | null = null;
  let bestD = Infinity;
  for (const el of els) {
    const p = px(el);
    const d = Math.abs(p.x - x) + Math.abs(p.y - y);
    if (d < bestD) { bestD = d; best = el; }
  }
  return best;
}

function ground(shot: Screenshot, want: string): { x: number; y: number } | null {
  for (const el of shot.elements) {
    if (el.label === want) return px(el);
  }
  return null;
}

function renderGrid(shot: Screenshot): string {
  const lines: string[] = [];
  for (let r = 0; r < 4; r++) {
    const parts: string[] = [];
    for (let c = 0; c < 3; c++) {
      let text = '.';
      for (const el of shot.elements) {
        if (el.col === c && el.row === r) text = el.label;
      }
      parts.push(text.padEnd(18).slice(0, 18));
    }
    const joined = parts.join('|');
    if (joined.replace(/[.| ]/g, '').length > 0) lines.push('    ' + joined);
  }
  return lines.join('\n');
}

// Model stub: pick the next action purely from what the screenshot shows.
function decide(shot: Screenshot): { action: string; label: string } {
  if (shot.popup) return { action: 'click', label: 'Consent: Accept' };
  if (shot.screen === 'home') return { action: 'click', label: 'Settings' };
  if (shot.screen === 'settings') return { action: 'click', label: 'Appearance' };
  if (shot.elements[0] && shot.elements[0].label === 'Dark Mode: OFF') {
    return { action: 'click', label: 'Dark Mode: OFF' };
  }
  return { action: 'done', label: '' };
}

function main() {
  const desk = new Desktop();
  console.log('Task: enable dark mode in the Settings app (screenshots + clicks only)\n');
  for (let cycle = 1; cycle <= 8; cycle++) {
    const shot = desk.screenshot();
    console.log(`--- cycle ${cycle} ---`);
    console.log(`[screenshot] screen=${shot.screen} popup=${shot.popup ? 'OPEN' : 'none'}`);
    console.log(renderGrid(shot));
    const plan = decide(shot);
    if (plan.action === 'done') {
      console.log('[reason] dark mode is ON; goal reached, stopping.\n');
      console.log('Result: dark mode enabled with no API, only screenshot -> ground -> click -> observe.');
      return;
    }
    const reason = shot.popup
      ? 'a consent popup is blocking the UI; dismiss it before continuing'
      : `advance toward the Dark Mode toggle by clicking "${plan.label}"`;
    console.log(`[reason] ${reason}`);
    const coords = ground(shot, plan.label);
    if (!coords) { console.log('[ground] target not found, retry'); continue; }
    console.log(`[ground] "${plan.label}" -> pixel (${coords.x},${coords.y})`);
    const before = JSON.stringify(desk.screenshot());
    desk.clickAt(coords.x, coords.y, shot);
    const after = JSON.stringify(desk.screenshot());
    console.log(`[act] click (${coords.x},${coords.y})`);
    console.log(`[observe] screen changed: ${before !== after ? 'yes' : 'no'}\n`);
  }
  console.log('Result: stopped after max cycles.');
}

main();

