#!/usr/bin/env python3
# Computer Use: an agent drives a GUI it can only perceive as screenshots.
# Each cycle it takes a screenshot (a text grid of labeled elements), grounds
# an intent to pixel coordinates, clicks, then observes whether the screen
# changed as expected, recovering from an unexpected consent popup.

from dataclasses import dataclass
from typing import List, Optional, Tuple

@dataclass
class Element:
    label: str
    col: int
    row: int

@dataclass
class Screenshot:
    screen: str
    popup: bool
    elements: List[Element]

class Desktop:
    def __init__(self) -> None:
        self.screen = "home"
        self.popup_open = True
        self.dark_mode = False

    def screenshot(self) -> Screenshot:
        if self.popup_open:
            return Screenshot(self.screen, True, [
                Element("Consent: Accept", 1, 1),
                Element("Consent: Decline", 2, 1),
            ])
        if self.screen == "home":
            return Screenshot("home", False, [
                Element("Settings", 0, 2),
                Element("Profile", 2, 2),
            ])
        if self.screen == "settings":
            return Screenshot("settings", False, [
                Element("General", 0, 1),
                Element("Appearance", 1, 1),
            ])
        label = "Dark Mode: ON" if self.dark_mode else "Dark Mode: OFF"
        return Screenshot("appearance", False, [Element(label, 1, 1)])

    # A click lands at pixel coords; the element nearest those pixels reacts.
    def click_at(self, x: int, y: int, shot: Screenshot) -> None:
        hit = nearest(shot.elements, x, y)
        if hit is None:
            return
        if hit.label.startswith("Consent:"):
            self.popup_open = False
        elif hit.label == "Settings":
            self.screen = "settings"
        elif hit.label == "Appearance":
            self.screen = "appearance"
        elif hit.label.startswith("Dark Mode"):
            self.dark_mode = not self.dark_mode

def px(el: Element) -> Tuple[int, int]:
    return (el.col * 100 + 50, el.row * 60 + 30)

def nearest(els: List[Element], x: int, y: int) -> Optional[Element]:
    best: Optional[Element] = None
    best_d = 10 ** 9
    for el in els:
        ex, ey = px(el)
        d = abs(ex - x) + abs(ey - y)
        if d < best_d:
            best_d, best = d, el
    return best

def ground(shot: Screenshot, want: str) -> Optional[Tuple[int, int]]:
    for el in shot.elements:
        if el.label == want:
            return px(el)
    return None

def render_grid(shot: Screenshot) -> str:
    lines: List[str] = []
    for r in range(4):
        parts: List[str] = []
        for c in range(3):
            text = "."
            for el in shot.elements:
                if el.col == c and el.row == r:
                    text = el.label
            parts.append(text.ljust(18)[:18])
        joined = "|".join(parts)
        if joined.replace(".", "").replace("|", "").strip():
            lines.append("    " + joined)
    return "\n".join(lines)

# Model stub: pick the next action purely from what the screenshot shows.
def decide(shot: Screenshot) -> Tuple[str, str]:
    if shot.popup:
        return ("click", "Consent: Accept")
    if shot.screen == "home":
        return ("click", "Settings")
    if shot.screen == "settings":
        return ("click", "Appearance")
    if shot.elements and shot.elements[0].label == "Dark Mode: OFF":
        return ("click", "Dark Mode: OFF")
    return ("done", "")

def main() -> None:
    desk = Desktop()
    print("Task: enable dark mode in the Settings app (screenshots + clicks only)\n")
    for cycle in range(1, 9):
        shot = desk.screenshot()
        print(f"--- cycle {cycle} ---")
        print(f"[screenshot] screen={shot.screen} popup={'OPEN' if shot.popup else 'none'}")
        print(render_grid(shot))
        action, label = decide(shot)
        if action == "done":
            print("[reason] dark mode is ON; goal reached, stopping.\n")
            print("Result: dark mode enabled with no API, only screenshot -> ground -> click -> observe.")
            return
        reason = ("a consent popup is blocking the UI; dismiss it before continuing"
                  if shot.popup else f'advance toward the Dark Mode toggle by clicking "{label}"')
        print(f"[reason] {reason}")
        coords = ground(shot, label)
        if coords is None:
            print("[ground] target not found, retry")
            continue
        print(f'[ground] "{label}" -> pixel {coords}')
        before = str(desk.screenshot())
        desk.click_at(coords[0], coords[1], shot)
        after = str(desk.screenshot())
        print(f"[act] click {coords}")
        print(f"[observe] screen changed: {'yes' if before != after else 'no'}\n")
    print("Result: stopped after max cycles.")

if __name__ == "__main__":
    main()

code.rust:
// Computer Use: an agent drives a GUI it can only perceive as screenshots.
// Each cycle it takes a screenshot (a text grid of labeled elements), grounds
// an intent to pixel coordinates, clicks, then observes whether the screen
// changed as expected, recovering from an unexpected consent popup.

#[derive(Clone)]
struct Element {
    label: String,
    col: i32,
    row: i32,
}

struct Screenshot {
    screen: String,
    popup: bool,
    elements: Vec<Element>,
}

struct Desktop {
    screen: String,
    popup_open: bool,
    dark_mode: bool,
}

fn el(label: &str, col: i32, row: i32) -> Element {
    Element { label: label.to_string(), col, row }
}

impl Desktop {
    fn new() -> Self {
        Desktop { screen: "home".to_string(), popup_open: true, dark_mode: false }
    }

    fn screenshot(&self) -> Screenshot {
        if self.popup_open {
            return Screenshot {
                screen: self.screen.clone(),
                popup: true,
                elements: vec![el("Consent: Accept", 1, 1), el("Consent: Decline", 2, 1)],
            };
        }
        if self.screen == "home" {
            return Screenshot { screen: "home".to_string(), popup: false,
                elements: vec![el("Settings", 0, 2), el("Profile", 2, 2)] };
        }
        if self.screen == "settings" {
            return Screenshot { screen: "settings".to_string(), popup: false,
                elements: vec![el("General", 0, 1), el("Appearance", 1, 1)] };
        }
        let label = if self.dark_mode { "Dark Mode: ON" } else { "Dark Mode: OFF" };
        Screenshot { screen: "appearance".to_string(), popup: false, elements: vec![el(label, 1, 1)] }
    }

    // A click lands at pixel coords; the element nearest those pixels reacts.
    fn click_at(&mut self, x: i32, y: i32, shot: &Screenshot) {
        if let Some(hit) = nearest(&shot.elements, x, y) {
            if hit.label.starts_with("Consent:") {
                self.popup_open = false;
            } else if hit.label == "Settings" {
                self.screen = "settings".to_string();
            } else if hit.label == "Appearance" {
                self.screen = "appearance".to_string();
            } else if hit.label.starts_with("Dark Mode") {
                self.dark_mode = !self.dark_mode;
            }
        }
    }
}

fn px(e: &Element) -> (i32, i32) {
    (e.col * 100 + 50, e.row * 60 + 30)
}

fn nearest<'a>(els: &'a [Element], x: i32, y: i32) -> Option<&'a Element> {
    let mut best: Option<&Element> = None;
    let mut best_d = i32::MAX;
    for e in els {
        let (ex, ey) = px(e);
        let d = (ex - x).abs() + (ey - y).abs();
        if d < best_d {
            best_d = d;
            best = Some(e);
        }
    }
    best
}

fn ground(shot: &Screenshot, want: &str) -> Option<(i32, i32)> {
    for e in &shot.elements {
        if e.label == want {
            return Some(px(e));
        }
    }
    None
}

fn render_grid(shot: &Screenshot) -> String {
    let mut lines: Vec<String> = Vec::new();
    for r in 0..4 {
        let mut parts: Vec<String> = Vec::new();
        for c in 0..3 {
            let mut text = String::from(".");
            for e in &shot.elements {
                if e.col == c && e.row == r {
                    text = e.label.clone();
                }
            }
            while text.chars().count() < 18 {
                text.push(' ');
            }
            let cell: String = text.chars().take(18).collect();
            parts.push(cell);
        }
        let joined = parts.join("|");
        let stripped: String = joined.chars().filter(|c| *c != '.' && *c != '|' && *c != ' ').collect();
        if !stripped.is_empty() {
            lines.push(format!("    {}", joined));
        }
    }
    lines.join("\n")
}

// Model stub: pick the next action purely from what the screenshot shows.
fn decide(shot: &Screenshot) -> (String, String) {
    if shot.popup {
        return ("click".to_string(), "Consent: Accept".to_string());
    }
    if shot.screen == "home" {
        return ("click".to_string(), "Settings".to_string());
    }
    if shot.screen == "settings" {
        return ("click".to_string(), "Appearance".to_string());
    }
    if !shot.elements.is_empty() && shot.elements[0].label == "Dark Mode: OFF" {
        return ("click".to_string(), "Dark Mode: OFF".to_string());
    }
    ("done".to_string(), String::new())
}

fn snapshot_string(d: &Desktop) -> String {
    format!("{}|{}|{}", d.screen, d.popup_open, d.dark_mode)
}

fn main() {
    let mut desk = Desktop::new();
    println!("Task: enable dark mode in the Settings app (screenshots + clicks only)\n");
    for cycle in 1..=8 {
        let shot = desk.screenshot();
        println!("--- cycle {} ---", cycle);
        println!("[screenshot] screen={} popup={}", shot.screen, if shot.popup { "OPEN" } else { "none" });
        println!("{}", render_grid(&shot));
        let (action, label) = decide(&shot);
        if action == "done" {
            println!("[reason] dark mode is ON; goal reached, stopping.\n");
            println!("Result: dark mode enabled with no API, only screenshot -> ground -> click -> observe.");
            return;
        }
        let reason = if shot.popup {
            "a consent popup is blocking the UI; dismiss it before continuing".to_string()
        } else {
            format!("advance toward the Dark Mode toggle by clicking \"{}\"", label)
        };
        println!("[reason] {}", reason);
        match ground(&shot, &label) {
            None => {
                println!("[ground] target not found, retry");
                continue;
            }
            Some((x, y)) => {
                println!("[ground] \"{}\" -> pixel ({},{})", label, x, y);
                let before = snapshot_string(&desk);
                desk.click_at(x, y, &shot);
                let after = snapshot_string(&desk);
                println!("[act] click ({},{})", x, y);
                println!("[observe] screen changed: {}\n", if before != after { "yes" } else { "no" });
            }
        }
    }
    println!("Result: stopped after max cycles.");
}

