// Agent Skills.
// Skills are self-contained folders (SKILL.md metadata + instructions + a
// bundled script). The agent discovers by metadata, loads one skill's full
// body only when matched, then runs its deterministic script. Context holds
// the active skill, not all installed ones.

interface Skill {
  name: string;
  description: string; // Level 1 metadata, always in context
  instructions: string; // Level 2 full SKILL.md body, loaded on activation
  fieldMap: Record<string, string>; // bundled resource used by the script
  run: (fieldMap: Record<string, string>, notes: Record<string, string>) => string[];
}

function words(text: string): number {
  return text.trim().split(/\s+/).filter(w => w.length > 0).length;
}

// Level 3 script for the pdf-form skill: deterministic field writer. The model
// never parses raw PDF bytes; the bundled script maps notes onto form fields.
function fillForm(fieldMap: Record<string, string>, notes: Record<string, string>): string[] {
  const lines: string[] = [];
  for (const [field, key] of Object.entries(fieldMap)) {
    lines.push(`  ${field}: ${notes[key] ?? '(left blank)'}`);
  }
  return lines;
}

const REGISTRY: Skill[] = [
  {
    name: 'pdf-form',
    description: 'fill PDF form fields from provided values',
    instructions: 'Read the form field labels, map each label to a note key, then call the bundled fill_form script to write values without parsing PDF bytes.',
    fieldMap: { 'Full Name': 'name', 'Annual Income': 'income', 'Filing Status': 'status' },
    run: fillForm,
  },
  {
    name: 'xlsx-report',
    description: 'build spreadsheets and pivot tables',
    instructions: 'Open the workbook, add sheets, and write formatted cells and pivots.',
    fieldMap: {},
    run: () => [],
  },
  {
    name: 'email-send',
    description: 'send an email through the outbound gateway',
    instructions: 'Compose headers and body, then hand off to the mail transport.',
    fieldMap: {},
    run: () => [],
  },
  {
    name: 'image-resize',
    description: 'resize and crop raster images',
    instructions: 'Decode the image, apply the resize filter, and re-encode.',
    fieldMap: {},
    run: () => [],
  },
];

function main() {
  console.log('Agent Skills, three-level progressive disclosure\n');

  const task = 'Fill out this PDF tax form using the values in my notes';
  const notes: Record<string, string> = { name: 'Dana Lee', income: '48,000', status: 'single' };
  console.log(`Task: ${task}`);
  console.log(`Installed skills: ${REGISTRY.map(s => s.name).join(', ')}\n`);

  // Level 1: scan only names and descriptions to judge relevance. Score each
  // skill by how many of its description keywords appear in the task.
  console.log('Level 1 discover: scan metadata (name + description) only');
  const taskWords = new Set(task.toLowerCase().split(/\s+/));
  let chosen: Skill | null = null;
  let bestScore = 0;
  for (const skill of REGISTRY) {
    const keywords = skill.description.toLowerCase().split(/\s+/).filter(w => w.length >= 3);
    const score = keywords.filter(w => taskWords.has(w)).length;
    console.log(`  ${skill.name.padEnd(12)} "${skill.description}" -> score ${score}`);
    if (score > bestScore) {
      bestScore = score;
      chosen = skill;
    }
  }
  if (!chosen) {
    console.log('No skill matched; answering without one.');
    return;
  }
  console.log(`  best match: ${chosen.name}`);

  // Level 2: activate the matched skill, loading its full SKILL.md body.
  console.log(`\nLevel 2 activate: load ${chosen.name}/SKILL.md full instructions`);
  console.log(`  ${chosen.instructions}`);

  // Level 3: execute the bundled deterministic script over bundled resources.
  console.log(`\nLevel 3 execute: run bundled fill_form script with field-map resource`);
  const filled = chosen.run(chosen.fieldMap, notes);
  console.log('Filled form:');
  for (const line of filled) console.log(line);

  // Context budget: metadata for all skills + one full skill, versus loading
  // every skill in full. Estimated in whitespace-separated tokens.
  const metaAll = REGISTRY.reduce((sum, s) => sum + words(s.name) + words(s.description), 0);
  const fullChosen = words(chosen.instructions);
  const used = metaAll + fullChosen;
  const ifAllFull = REGISTRY.reduce((sum, s) => sum + words(s.name) + words(s.description) + words(s.instructions), 0);
  console.log('\nContext budget (estimated tokens):');
  console.log(`  metadata for all ${REGISTRY.length} skills: ${metaAll}`);
  console.log(`  + full body of ${chosen.name} only        : ${fullChosen}`);
  console.log(`  = used                                    : ${used}`);
  console.log(`  vs loading every skill in full            : ${ifAllFull}`);
  console.log(`\nOnly 1 of ${REGISTRY.length} skills loaded fully; context stayed small.`);
}

main();

code.rust:
// Agent Skills.
// Skills are self-contained folders (SKILL.md metadata + instructions + a
// bundled script). The agent discovers by metadata, loads one skill's full
// body only when matched, then runs its deterministic script. Context holds
// the active skill, not all installed ones.

type Pairs = Vec<(&'static str, &'static str)>;

struct Skill {
    name: &'static str,
    description: &'static str,  // Level 1 metadata, always in context
    instructions: &'static str, // Level 2 full SKILL.md body, loaded on activation
    field_map: Pairs,           // bundled resource used by the script
    run: fn(&Pairs, &Pairs) -> Vec<String>,
}

fn words(text: &str) -> usize {
    text.split_whitespace().count()
}

// Level 3 script for the pdf-form skill: deterministic field writer. The model
// never parses raw PDF bytes; the bundled script maps notes onto form fields.
fn fill_form(field_map: &Pairs, notes: &Pairs) -> Vec<String> {
    let mut lines = Vec::new();
    for (form_field, key) in field_map {
        let value = notes.iter().find(|(k, _)| k == key).map(|(_, v)| *v).unwrap_or("(left blank)");
        lines.push(format!("  {}: {}", form_field, value));
    }
    lines
}

fn no_op(_field_map: &Pairs, _notes: &Pairs) -> Vec<String> {
    Vec::new()
}

fn registry() -> Vec<Skill> {
    vec![
        Skill {
            name: "pdf-form",
            description: "fill PDF form fields from provided values",
            instructions: "Read the form field labels, map each label to a note key, then call the bundled fill_form script to write values without parsing PDF bytes.",
            field_map: vec![("Full Name", "name"), ("Annual Income", "income"), ("Filing Status", "status")],
            run: fill_form,
        },
        Skill {
            name: "xlsx-report",
            description: "build spreadsheets and pivot tables",
            instructions: "Open the workbook, add sheets, and write formatted cells and pivots.",
            field_map: vec![],
            run: no_op,
        },
        Skill {
            name: "email-send",
            description: "send an email through the outbound gateway",
            instructions: "Compose headers and body, then hand off to the mail transport.",
            field_map: vec![],
            run: no_op,
        },
        Skill {
            name: "image-resize",
            description: "resize and crop raster images",
            instructions: "Decode the image, apply the resize filter, and re-encode.",
            field_map: vec![],
            run: no_op,
        },
    ]
}

fn main() {
    println!("Agent Skills, three-level progressive disclosure\n");

    let task = "Fill out this PDF tax form using the values in my notes";
    let notes: Pairs = vec![("name", "Dana Lee"), ("income", "48,000"), ("status", "single")];
    let skills = registry();
    let names: Vec<&str> = skills.iter().map(|s| s.name).collect();
    println!("Task: {}", task);
    println!("Installed skills: {}\n", names.join(", "));

    // Level 1: scan only names and descriptions to judge relevance. Score each
    // skill by how many of its description keywords appear in the task.
    println!("Level 1 discover: scan metadata (name + description) only");
    let task_words: Vec<String> = task.to_lowercase().split_whitespace().map(|w| w.to_string()).collect();
    let mut chosen: Option<&Skill> = None;
    let mut best_score = 0;
    for skill in &skills {
        let score = skill
            .description
            .to_lowercase()
            .split_whitespace()
            .filter(|w| w.len() >= 3)
            .filter(|w| task_words.iter().any(|t| t == w))
            .count();
        println!("  {:<12} \"{}\" -> score {}", skill.name, skill.description, score);
        if score > best_score {
            best_score = score;
            chosen = Some(skill);
        }
    }
    let chosen = match chosen {
        Some(s) => s,
        None => {
            println!("No skill matched; answering without one.");
            return;
        }
    };
    println!("  best match: {}", chosen.name);

    // Level 2: activate the matched skill, loading its full SKILL.md body.
    println!("\nLevel 2 activate: load {}/SKILL.md full instructions", chosen.name);
    println!("  {}", chosen.instructions);

    // Level 3: execute the bundled deterministic script over bundled resources.
    println!("\nLevel 3 execute: run bundled fill_form script with field-map resource");
    let filled = (chosen.run)(&chosen.field_map, &notes);
    println!("Filled form:");
    for line in &filled {
        println!("{}", line);
    }

    // Context budget: metadata for all skills + one full skill, versus loading
    // every skill in full. Estimated in whitespace-separated tokens.
    let meta_all: usize = skills.iter().map(|s| words(s.name) + words(s.description)).sum();
    let full_chosen = words(chosen.instructions);
    let used = meta_all + full_chosen;
    let if_all_full: usize = skills
        .iter()
        .map(|s| words(s.name) + words(s.description) + words(s.instructions))
        .sum();
    println!("\nContext budget (estimated tokens):");
    println!("  metadata for all {} skills: {}", skills.len(), meta_all);
    println!("  + full body of {} only        : {}", chosen.name, full_chosen);
    println!("  = used                                    : {}", used);
    println!("  vs loading every skill in full            : {}", if_all_full);
    println!("\nOnly 1 of {} skills loaded fully; context stayed small.", skills.len());
}

code.typescript:
// Tool Retrieval (Tool RAG): with a large tool catalog, loading every schema is
// costly and confuses selection. Here a keyword-overlap scorer stands in for an
// embedding retriever: it scores each tool against the query, reranks, keeps the
// top-k, and only those schemas enter the prompt. The model then selects a
// pipeline from that shortlist. The demo prints scores and the token savings.

interface Tool {
  name: string;
  description: string;
  schemaTokens: number;
}

const TOP_K = 5;

// A tiny slice of a much larger catalog. In production this is thousands of tools.
const catalog: Tool[] = [
  { name: 'pdf_extract', description: 'extract text and tables from pdf invoice documents', schemaTokens: 160 },
  { name: 'table_to_csv', description: 'convert extracted tables into csv files', schemaTokens: 140 },
  { name: 'email_send', description: 'send an email with csv attachments to a recipient', schemaTokens: 150 },
  { name: 'ocr_scan', description: 'read text from scanned invoice images', schemaTokens: 150 },
  { name: 'sheet_read', description: 'read tabular data to export as csv', schemaTokens: 130 },
  { name: 'image_resize', description: 'resize and crop raster images', schemaTokens: 120 },
  { name: 'translate_text', description: 'translate text between languages', schemaTokens: 120 },
  { name: 'calendar_create', description: 'create a calendar event with attendees', schemaTokens: 130 },
  { name: 'weather_lookup', description: 'current weather for a city', schemaTokens: 110 },
  { name: 'sql_query', description: 'run a read-only query against a database', schemaTokens: 160 },
  { name: 'stock_quote', description: 'latest price for a stock ticker', schemaTokens: 110 },
  { name: 'geocode_address', description: 'turn a street address into coordinates', schemaTokens: 130 },
  { name: 'sentiment_score', description: 'rate the sentiment of a passage of text', schemaTokens: 120 },
  { name: 'video_transcode', description: 're-encode a video into another format', schemaTokens: 150 },
];

function tokenize(text: string): string[] {
  return text.toLowerCase().split(/[^a-z]+/).filter(w => w.length > 2);
}

// Keyword-overlap score in [0, 1], a deterministic stand-in for cosine similarity.
function score(query: string, tool: Tool): number {
  const q = new Set(tokenize(query));
  const words = tokenize(tool.name.replace(/_/g, ' ') + ' ' + tool.description);
  if (q.size === 0) return 0;
  let hits = 0;
  const seen = new Set<string>();
  for (const w of words) {
    if (q.has(w) && !seen.has(w)) {
      hits += 1;
      seen.add(w);
    }
  }
  return hits / q.size;
}

// Deterministic half-up rounding via floor, so TS, Python, and Rust agree.
function pct2(s: number): string {
  const r = Math.floor(s * 100 + 0.5);
  return `${Math.floor(r / 100)}.${String(r % 100).padStart(2, '0')}`;
}

function bar(frac: number): string {
  const cells = 12;
  const filled = Math.floor(frac * cells + 0.5);
  return '[' + '#'.repeat(filled) + '-'.repeat(cells - filled) + ']';
}

function main() {
  const query = 'Convert this invoice PDF to CSV and email it to finance';
  console.log('=== Tool Retrieval (Tool RAG) ===');
  console.log(`query: ${query}`);
  console.log(`catalog: ${catalog.length} tools loaded here (stands in for thousands)`);

  const ranked = catalog
    .map(tool => ({ tool, s: score(query, tool) }))
    .sort((a, b) => b.s - a.s || a.tool.name.localeCompare(b.tool.name));

  console.log('\nretrieve + rerank (top scores):');
  for (const { tool, s } of ranked.slice(0, TOP_K + 2)) {
    console.log(`  ${bar(s)} ${pct2(s)}  ${tool.name}`);
  }

  const shortlist = ranked.slice(0, TOP_K).filter(r => r.s > 0);
  console.log(`\nshortlist: load only top ${shortlist.length} schemas -> [${shortlist.map(r => r.tool.name).join(', ')}]`);

  const pickedTokens = shortlist.reduce((sum, r) => sum + r.tool.schemaTokens, 0);
  const allTokens = catalog.reduce((sum, t) => sum + t.schemaTokens, 0);
  console.log(`prompt tokens: ${pickedTokens} (shortlist) vs ${allTokens} (whole catalog)`);
  console.log(`saved: ${allTokens - pickedTokens} tokens by not loading irrelevant schemas`);

  // Model selects an ordered pipeline from the small, focused schema set.
  const names = shortlist.map(r => r.tool.name);
  const pipeline = ['pdf_extract', 'table_to_csv', 'email_send'].filter(n => names.includes(n));
  console.log(`\nmodel selects pipeline: ${pipeline.join(' -> ')}`);
  console.log('  pdf_extract  -> tables pulled from the invoice');
  console.log('  table_to_csv -> rows written to invoice.csv');
  console.log('  email_send   -> invoice.csv delivered to finance');
  console.log('\nresult: correct tools chosen from a focused shortlist, at a fraction of the token cost');
}

main();

code.rust:
// Tool Retrieval (Tool RAG): with a large tool catalog, loading every schema is
// costly and confuses selection. Here a keyword-overlap scorer stands in for an
// embedding retriever: it scores each tool against the query, reranks, keeps the
// top-k, and only those schemas enter the prompt. The model then selects a
// pipeline from that shortlist. The demo prints scores and the token savings.

use std::collections::HashSet;

const TOP_K: usize = 5;

struct Tool {
    name: &'static str,
    description: &'static str,
    schema_tokens: i64,
}

fn tokenize(text: &str) -> Vec<String> {
    text.to_lowercase()
        .split(|c: char| !c.is_ascii_alphabetic())
        .filter(|w| w.len() > 2)
        .map(|w| w.to_string())
        .collect()
}

// Keyword-overlap score in [0, 1], a deterministic stand-in for cosine similarity.
fn score(query: &str, tool: &Tool) -> f64 {
    let q: HashSet<String> = tokenize(query).into_iter().collect();
    if q.is_empty() {
        return 0.0;
    }
    let text = format!("{} {}", tool.name.replace('_', " "), tool.description);
    let words: HashSet<String> = tokenize(&text).into_iter().collect();
    let hits = q.intersection(&words).count();
    hits as f64 / q.len() as f64
}

// Deterministic half-up rounding via floor, so TS, Python, and Rust agree.
fn pct2(s: f64) -> String {
    let r = (s * 100.0 + 0.5) as i64;
    format!("{}.{:02}", r / 100, r % 100)
}

fn bar(frac: f64) -> String {
    let cells = 12;
    let filled = (frac * cells as f64 + 0.5) as usize;
    format!("[{}{}]", "#".repeat(filled), "-".repeat(cells - filled))
}

fn main() {
    let query = "Convert this invoice PDF to CSV and email it to finance";
    let catalog = vec![
        Tool { name: "pdf_extract", description: "extract text and tables from pdf invoice documents", schema_tokens: 160 },
        Tool { name: "table_to_csv", description: "convert extracted tables into csv files", schema_tokens: 140 },
        Tool { name: "email_send", description: "send an email with csv attachments to a recipient", schema_tokens: 150 },
        Tool { name: "ocr_scan", description: "read text from scanned invoice images", schema_tokens: 150 },
        Tool { name: "sheet_read", description: "read tabular data to export as csv", schema_tokens: 130 },
        Tool { name: "image_resize", description: "resize and crop raster images", schema_tokens: 120 },
        Tool { name: "translate_text", description: "translate text between languages", schema_tokens: 120 },
        Tool { name: "calendar_create", description: "create a calendar event with attendees", schema_tokens: 130 },
        Tool { name: "weather_lookup", description: "current weather for a city", schema_tokens: 110 },
        Tool { name: "sql_query", description: "run a read-only query against a database", schema_tokens: 160 },
        Tool { name: "stock_quote", description: "latest price for a stock ticker", schema_tokens: 110 },
        Tool { name: "geocode_address", description: "turn a street address into coordinates", schema_tokens: 130 },
        Tool { name: "sentiment_score", description: "rate the sentiment of a passage of text", schema_tokens: 120 },
        Tool { name: "video_transcode", description: "re-encode a video into another format", schema_tokens: 150 },
    ];

    println!("=== Tool Retrieval (Tool RAG) ===");
    println!("query: {}", query);
    println!("catalog: {} tools loaded here (stands in for thousands)", catalog.len());

    let mut ranked: Vec<&Tool> = catalog.iter().collect();
    ranked.sort_by(|a, b| {
        let sb = score(query, b);
        let sa = score(query, a);
        sb.partial_cmp(&sa).unwrap().then(a.name.cmp(b.name))
    });

    println!("\nretrieve + rerank (top scores):");
    for tool in ranked.iter().take(TOP_K + 2) {
        let s = score(query, tool);
        println!("  {} {}  {}", bar(s), pct2(s), tool.name);
    }

    let shortlist: Vec<&&Tool> = ranked.iter().take(TOP_K).filter(|t| score(query, t) > 0.0).collect();
    let names: Vec<&str> = shortlist.iter().map(|t| t.name).collect();
    println!("\nshortlist: load only top {} schemas -> [{}]", shortlist.len(), names.join(", "));

    let picked_tokens: i64 = shortlist.iter().map(|t| t.schema_tokens).sum();
    let all_tokens: i64 = catalog.iter().map(|t| t.schema_tokens).sum();
    println!("prompt tokens: {} (shortlist) vs {} (whole catalog)", picked_tokens, all_tokens);
    println!("saved: {} tokens by not loading irrelevant schemas", all_tokens - picked_tokens);

    // Model selects an ordered pipeline from the small, focused schema set.
    let pipeline: Vec<&str> = ["pdf_extract", "table_to_csv", "email_send"]
        .into_iter()
        .filter(|n| names.contains(n))
        .collect();
    println!("\nmodel selects pipeline: {}", pipeline.join(" -> "));
    println!("  pdf_extract  -> tables pulled from the invoice");
    println!("  table_to_csv -> rows written to invoice.csv");
    println!("  email_send   -> invoice.csv delivered to finance");
    println!("\nresult: correct tools chosen from a focused shortlist, at a fraction of the token cost");
}

