// Structured Outputs: constrained decoding against a JSON schema. The schema is
// compiled to a finite-state machine; at every decode step the tokens that would
// break the schema are masked out, so the model can only emit a valid continuation.
// Here we classify a support ticket into a fixed shape and watch invalid tokens fail.

function isDigit(t: string): boolean {
  return t.length === 1 && t >= '0' && t <= '9';
}

// Enum field: the FSM allows only the schema's literal values.
function constrainedChoice(field: string, allowed: string[], ranks: string[]): string {
  console.log(`  field '${field}' (enum ${allowed.join('|')})`);
  console.log(`     model ranks: ${ranks.join(', ')}`);
  for (const tok of ranks) {
    if (allowed.includes(tok)) {
      console.log(`       token '${tok}' ALLOWED -> emit`);
      return tok;
    }
    console.log(`       token '${tok}' BLOCKED (not in enum)`);
  }
  return allowed[0];
}

// Number field: digits, at most one decimal point, and a STOP that ends on a digit.
function numberAllowed(tok: string, state: string): boolean {
  if (tok === 'STOP') return state.length > 0 && isDigit(state[state.length - 1]);
  if (tok === '.') return !state.includes('.');
  return isDigit(tok);
}

function constrainedNumber(field: string, steps: string[][]): string {
  console.log(`  field '${field}' (number)`);
  let state = '';
  let step = 0;
  for (const ranks of steps) {
    step += 1;
    console.log(`     step ${step} ranks: ${ranks.join(', ')}`);
    for (const tok of ranks) {
      if (numberAllowed(tok, state)) {
        if (tok === 'STOP') {
          console.log(`       'STOP' ALLOWED -> end number`);
          return state;
        }
        console.log(`       '${tok}' ALLOWED -> emit`);
        state += tok;
        break;
      }
      const why = tok === '.' ? 'second decimal point' : 'not a number token';
      console.log(`       '${tok}' BLOCKED (${why})`);
    }
  }
  return state;
}

function main() {
  console.log("Task: extract {category: bug|billing|feature, priority: low|high, hours: number}");
  console.log("      from a support ticket, output constrained to a JSON schema.");
  console.log('Ticket: "billing charged me twice, please refund; took about 3.5 hours to notice"\n');
  console.log('Compiling schema to an FSM... done. Decoding under per-step token masks:\n');

  const category = constrainedChoice('category', ['bug', 'billing', 'feature'], ['refund', 'billing', 'bug']);
  const priority = constrainedChoice('priority', ['low', 'high'], ['urgent', 'high']);
  const hours = constrainedNumber('hours', [['3', 'x'], ['.', ','], ['5'], ['.', 'STOP']]);

  const json = `{"category":"${category}","priority":"${priority}","hours":${hours}}`;
  console.log(`\nConstrained output: ${json}`);
  // Guaranteed valid by construction, so parse directly with no repair pass.
  const parsed = JSON.parse(json);
  console.log('Downstream parse (no repair, no try/except): OK');
  console.log(`  category=${parsed.category} priority=${parsed.priority} hours=${parsed.hours}`);
}

main();

code.rust:
// Structured Outputs: constrained decoding against a JSON schema. The schema is
// compiled to a finite-state machine; at every decode step the tokens that would
// break the schema are masked out, so the model can only emit a valid continuation.
// Here we classify a support ticket into a fixed shape and watch invalid tokens fail.

fn is_digit(t: &str) -> bool {
    t.len() == 1 && t.chars().all(|c| c.is_ascii_digit())
}

// Enum field: the FSM allows only the schema's literal values.
fn constrained_choice(field: &str, allowed: &[&str], ranks: &[&str]) -> String {
    println!("  field '{}' (enum {})", field, allowed.join("|"));
    println!("     model ranks: {}", ranks.join(", "));
    for tok in ranks {
        if allowed.contains(tok) {
            println!("       token '{}' ALLOWED -> emit", tok);
            return tok.to_string();
        }
        println!("       token '{}' BLOCKED (not in enum)", tok);
    }
    allowed[0].to_string()
}

// Number field: digits, at most one decimal point, and a STOP that ends on a digit.
fn number_allowed(tok: &str, state: &str) -> bool {
    if tok == "STOP" {
        return !state.is_empty() && state.chars().last().map_or(false, |c| c.is_ascii_digit());
    }
    if tok == "." {
        return !state.contains('.');
    }
    is_digit(tok)
}

fn constrained_number(field: &str, steps: &[Vec<&str>]) -> String {
    println!("  field '{}' (number)", field);
    let mut state = String::new();
    for (i, ranks) in steps.iter().enumerate() {
        println!("     step {} ranks: {}", i + 1, ranks.join(", "));
        for tok in ranks {
            if number_allowed(tok, &state) {
                if *tok == "STOP" {
                    println!("       'STOP' ALLOWED -> end number");
                    return state;
                }
                println!("       '{}' ALLOWED -> emit", tok);
                state.push_str(tok);
                break;
            }
            let why = if *tok == "." { "second decimal point" } else { "not a number token" };
            println!("       '{}' BLOCKED ({})", tok, why);
        }
    }
    state
}

fn main() {
    println!("Task: extract {{category: bug|billing|feature, priority: low|high, hours: number}}");
    println!("      from a support ticket, output constrained to a JSON schema.");
    println!("Ticket: \"billing charged me twice, please refund; took about 3.5 hours to notice\"\n");
    println!("Compiling schema to an FSM... done. Decoding under per-step token masks:\n");

    let category = constrained_choice("category", &["bug", "billing", "feature"], &["refund", "billing", "bug"]);
    let priority = constrained_choice("priority", &["low", "high"], &["urgent", "high"]);
    let hours = constrained_number("hours", &[vec!["3", "x"], vec![".", ","], vec!["5"], vec![".", "STOP"]]);

    let text = format!("{{\"category\":\"{}\",\"priority\":\"{}\",\"hours\":{}}}", category, priority, hours);
    println!("\nConstrained output: {}", text);
    // Guaranteed valid by construction; consume the number field directly with no repair.
    let hours_val: f64 = hours.parse().unwrap();
    println!("Downstream parse (no repair, no error branch): OK");
    println!("  category={} priority={} hours={}", category, priority, hours_val);
}

code.typescript:
// Code as Action (CodeAct).
// The agent's action is one structured program (loops, conditionals,
// variables) that orchestrates three tools over 500 orders in a single turn.
// A tiny interpreter walks the fixed op structure; nothing is eval'd. The 500
// intermediate records stay in the runtime, and only the final total returns.

interface LoadOp { kind: 'load'; result: string; tool: string; arg: string; }
interface CallOp { kind: 'call'; result: string; tool: string; args: string[]; }
interface GuardOp { kind: 'guard'; ref: string; lessThan: number; into: string; add: string[]; }
interface ForeachOp { kind: 'foreach'; itemVar: string; listVar: string; body: (CallOp | GuardOp)[]; }
interface ReturnOp { kind: 'return'; ref: string; }
type Op = LoadOp | ForeachOp | ReturnOp;

const TODAY = 15;
const RATES: Record<string, number> = { eu: 0.2, us: 0.08, apac: 0.1, latam: 0.15 };

// Simulated tools. Each returns canned-but-deterministic data.
function readCsv(): Record<string, number>[] {
  const rows: Record<string, number>[] = [];
  for (let i = 0; i < 500; i++) {
    rows.push({ id: i, customer_id: 1 + (i % 20), amount: 50 + ((i * 37) % 950), due_day: 1 + ((i * 7) % 28) });
  }
  return rows;
}
function getCustomer(id: number): Record<string, any> {
  const regions = ['eu', 'us', 'apac', 'latam'];
  return { id, region: regions[id % regions.length] };
}
function computeTax(amount: number, region: string): number {
  return Math.round(amount * RATES[region] * 100) / 100;
}

const TOOLS: Record<string, (args: any[]) => any> = {
  read_csv: () => readCsv(),
  get_customer: args => getCustomer(args[0]),
  compute_tax: args => computeTax(args[0], args[1]),
};

// Resolve a reference like "r.amount" or a plain var like "tax" from runtime.
function resolve(runtime: Record<string, any>, ref: string): any {
  if (ref.includes('.')) {
    const parts = ref.split('.');
    return runtime[parts[0]][parts[1]];
  }
  return runtime[ref];
}

interface Stats { toolCalls: number; rows: number; overdue: number; records: number; }

// The interpreter: one turn executes the whole program, tools included.
function runProgram(program: Op[]): { total: number; stats: Stats } {
  const runtime: Record<string, any> = { total: 0 };
  const stats: Stats = { toolCalls: 0, rows: 0, overdue: 0, records: 0 };
  let returned = 0;
  for (const op of program) {
    if (op.kind === 'load') {
      runtime[op.result] = TOOLS[op.tool]([op.arg]);
      stats.toolCalls++;
      stats.rows = runtime[op.result].length;
    } else if (op.kind === 'foreach') {
      for (const item of runtime[op.listVar]) {
        runtime[op.itemVar] = item;
        for (const step of op.body) {
          if (step.kind === 'call') {
            const args = step.args.map(a => resolve(runtime, a));
            runtime[step.result] = TOOLS[step.tool](args);
            stats.toolCalls++;
            if (step.tool === 'get_customer') stats.records++; // stays in runtime
          } else {
            if (resolve(runtime, step.ref) < step.lessThan) {
              const delta = step.add.reduce((sum, a) => sum + resolve(runtime, a), 0);
              runtime[step.into] = runtime[step.into] + delta;
              stats.overdue++;
            }
          }
        }
      }
    } else if (op.kind === 'return') {
      returned = runtime[op.ref];
    }
  }
  return { total: returned, stats };
}

function main() {
  console.log('Code as Action, one program orchestrates 3 tools over 500 orders\n');

  // The agent's single code action, expressed as a fixed op structure.
  const program: Op[] = [
    { kind: 'load', result: 'rows', tool: 'read_csv', arg: 'orders.csv' },
    {
      kind: 'foreach',
      itemVar: 'r',
      listVar: 'rows',
      body: [
        { kind: 'call', result: 'c', tool: 'get_customer', args: ['r.customer_id'] },
        { kind: 'call', result: 'tax', tool: 'compute_tax', args: ['r.amount', 'c.region'] },
        { kind: 'guard', ref: 'r.due_day', lessThan: TODAY, into: 'total', add: ['r.amount', 'tax'] },
      ],
    },
    { kind: 'return', ref: 'total' },
  ];

  console.log('Code action (interpreted, never eval\'d):');
  console.log('  rows = read_csv("orders.csv")');
  console.log('  total = 0');
  console.log('  for r in rows:');
  console.log('      c = get_customer(r.customer_id)');
  console.log('      tax = compute_tax(r.amount, c.region)');
  console.log(`      if r.due_day < ${TODAY}:`);
  console.log('          total += r.amount + tax');
  console.log('  return total\n');

  const { total, stats } = runProgram(program);

  console.log('Execution (single turn):');
  console.log(`  rows processed        : ${stats.rows}`);
  console.log(`  tool calls made       : ${stats.toolCalls} (read_csv + 2 per row)`);
  console.log(`  customer records built: ${stats.records} (kept in runtime, never returned)`);
  console.log(`  overdue orders        : ${stats.overdue}`);
