// Structured Reflection (Think Tool): a dedicated no-op "think" tool sits in the
// agent's schema. Calling it takes no external action and returns no data; it
// only parks structured reasoning in context. This demo runs the same airline
// booking task twice, without and with the checkpoint, to show how the parked
// reasoning steers the agent away from a policy violation.

interface Reservation {
  fare: string;
  bookedMinutesAgo: number;
}

interface Context {
  log: string[];
  plan: string[];
}

const FREE_CANCEL_WINDOW_MIN = 24 * 60;

const reservation: Reservation = { fare: 'basic-economy', bookedMinutesAgo: 20 };

// Tools with canned effects. change_flight is illegal on a non-changeable fare.
function getReservation(r: Reservation): string {
  return `${r.fare}, booked ${r.bookedMinutesAgo} min ago`;
}
function changeFlight(r: Reservation): string {
  if (r.fare === 'basic-economy') return 'POLICY VIOLATION: basic-economy fare is non-changeable';
  return 'flight changed';
}
function cancelBooking(r: Reservation): string {
  const free = r.bookedMinutesAgo <= FREE_CANCEL_WINDOW_MIN;
  return free ? 'cancelled free (within 24h window)' : 'cancelled with penalty';
}
function bookFlight(): string {
  return 'booked tomorrow 08:10, new fare quoted and confirmed';
}

// The no-op think tool: it records reasoning and a plan into context, then
// returns nothing. No booking system is touched by this call.
function think(ctx: Context, notes: string[], plan: string[]): string {
  for (const n of notes) ctx.log.push(n);
  ctx.plan = plan;
  return '';
}

// Build the reflection a competent agent would write at the checkpoint.
function reflect(ctx: Context, r: Reservation): void {
  think(
    ctx,
    [
      'basic economy is non-changeable',
      `booked ${r.bookedMinutesAgo} min ago, inside the 24h free-cancel window`,
      'so cancel-and-rebook is allowed, a direct change is not',
    ],
    ['cancel_booking', 'book_flight'],
  );
}

function runTrajectory(useThink: boolean): boolean {
  const label = useThink ? 'with the think tool' : 'no think tool';
  console.log(`\n--- Trajectory: ${label} ---`);
  const ctx: Context = { log: [], plan: [] };

  console.log(`  tool_call get_reservation() -> ${getReservation(reservation)}`);

  if (useThink) {
    reflect(ctx, reservation);
    console.log('  tool_call think() [no-op] checkpoint:');
    for (const note of ctx.log) console.log(`     - ${note}`);
    console.log('     (think returned nothing; the reasoning is now in context)');
  }

  let legal = true;
  if (ctx.plan.length > 0) {
    console.log('  agent follows the checkpoint plan');
    for (const step of ctx.plan) {
      if (step === 'cancel_booking') console.log(`  tool_call cancel_booking() -> ${cancelBooking(reservation)}`);
      if (step === 'book_flight') console.log(`  tool_call book_flight() -> ${bookFlight()}`);
    }
  } else {
    console.log('  agent acts immediately on the result');
    const outcome = changeFlight(reservation);
    console.log(`  tool_call change_flight() -> ${outcome}`);
    legal = !outcome.startsWith('POLICY VIOLATION');
  }

  console.log(`  outcome: ${legal ? 'booking changed legally, violation avoided' : 'illegal change attempted'}`);
  return legal;
}

function main() {
  console.log('=== Structured Reflection (Think Tool) ===');
  console.log(`reservation: ${getReservation(reservation)}`);
  console.log('policy: basic economy is non-changeable; 24h free-cancellation window');

  const withoutThink = runTrajectory(false);
  const withThink = runTrajectory(true);

  console.log('\nsummary:');
  console.log(`  without think -> ${withoutThink ? 'legal' : 'policy violation'}`);
  console.log(`  with think    -> ${withThink ? 'legal' : 'policy violation'}`);
  console.log('  the no-op call added no data and touched no system, but the reasoning it');
  console.log('  parked in context steered the agent onto a compliant path.');
}

main();

