const FREE_CANCEL_WINDOW_MIN: i64 = 24 * 60;

struct Reservation {
    fare: String,
    booked_minutes_ago: i64,
}

struct Context {
    log: Vec<String>,
    plan: Vec<String>,
}

// Tools with canned effects. change_flight is illegal on a non-changeable fare.
fn get_reservation(r: &Reservation) -> String {
    format!("{}, booked {} min ago", r.fare, r.booked_minutes_ago)
}

fn change_flight(r: &Reservation) -> String {
    if r.fare == "basic-economy" {
        "POLICY VIOLATION: basic-economy fare is non-changeable".to_string()
    } else {
        "flight changed".to_string()
    }
}

fn cancel_booking(r: &Reservation) -> String {
    if r.booked_minutes_ago <= FREE_CANCEL_WINDOW_MIN {
        "cancelled free (within 24h window)".to_string()
    } else {
        "cancelled with penalty".to_string()
    }
}

fn book_flight() -> String {
    "booked tomorrow 08:10, new fare quoted and confirmed".to_string()
}

// The no-op think tool: it records reasoning and a plan into context, then
// returns nothing. No booking system is touched by this call.
fn think(ctx: &mut Context, notes: Vec<String>, plan: Vec<String>) -> String {
    ctx.log.extend(notes);
    ctx.plan = plan;
    String::new()
}

// Build the reflection a competent agent would write at the checkpoint.
fn reflect(ctx: &mut Context, r: &Reservation) {
    think(
        ctx,
        vec![
            "basic economy is non-changeable".to_string(),
            format!("booked {} min ago, inside the 24h free-cancel window", r.booked_minutes_ago),
            "so cancel-and-rebook is allowed, a direct change is not".to_string(),
        ],
        vec!["cancel_booking".to_string(), "book_flight".to_string()],
    );
}

fn run_trajectory(reservation: &Reservation, use_think: bool) -> bool {
    let label = if use_think { "with the think tool" } else { "no think tool" };
    println!("\n--- Trajectory: {} ---", label);
    let mut ctx = Context { log: Vec::new(), plan: Vec::new() };

    println!("  tool_call get_reservation() -> {}", get_reservation(reservation));

    if use_think {
        reflect(&mut ctx, reservation);
        println!("  tool_call think() [no-op] checkpoint:");
        for note in &ctx.log {
            println!("     - {}", note);
        }
        println!("     (think returned nothing; the reasoning is now in context)");
    }

    let mut legal = true;
    if !ctx.plan.is_empty() {
        println!("  agent follows the checkpoint plan");
        for step in &ctx.plan {
            if step == "cancel_booking" {
                println!("  tool_call cancel_booking() -> {}", cancel_booking(reservation));
            }
            if step == "book_flight" {
                println!("  tool_call book_flight() -> {}", book_flight());
            }
        }
    } else {
        println!("  agent acts immediately on the result");
        let outcome = change_flight(reservation);
        println!("  tool_call change_flight() -> {}", outcome);
        legal = !outcome.starts_with("POLICY VIOLATION");
    }

    let verdict = if legal {
        "booking changed legally, violation avoided"
    } else {
        "illegal change attempted"
    };
    println!("  outcome: {}", verdict);
    legal
}

fn main() {
    let reservation = Reservation { fare: "basic-economy".to_string(), booked_minutes_ago: 20 };

    println!("=== Structured Reflection (Think Tool) ===");
    println!("reservation: {}", get_reservation(&reservation));
    println!("policy: basic economy is non-changeable; 24h free-cancellation window");

    let without_think = run_trajectory(&reservation, false);
    let with_think = run_trajectory(&reservation, true);

    println!("\nsummary:");
    println!("  without think -> {}", if without_think { "legal" } else { "policy violation" });
    println!("  with think    -> {}", if with_think { "legal" } else { "policy violation" });
    println!("  the no-op call added no data and touched no system, but the reasoning it");
    println!("  parked in context steered the agent onto a compliant path.");
}

code.typescript:
// MCP Gateway (Tool Federation and Governance): one governed entrypoint sits in
// front of several backend MCP servers. Every call is authenticated, resolved by
// namespace to a backend, checked against a per-caller allowlist, rate-limited,
// proxied with a scoped downstream credential the agent never sees, and audited.

interface BackendServer {
  name: string;
  tools: string[];
  credential: string; // held by the gateway, never exposed to the caller
  handle: (tool: string, args: Record<string, string>, cred: string) => string;
}

interface Request {
  token: string;
  tool: string; // namespaced: "server.tool"
  args: Record<string, string>;
}

class Gateway {
  private servers = new Map<string, BackendServer>();
  private tokens = new Map<string, string>();
  private allow = new Map<string, string[]>();
  private audit: string[] = [];
  private used = 0;
  private quota = 60; // calls per minute

  federate(server: BackendServer): void {
    this.servers.set(server.name, server);
  }

  grant(token: string, identity: string, tools: string[]): void {
    this.tokens.set(token, identity);
    this.allow.set(identity, tools);
  }

  private record(caller: string, tool: string, backend: string, decision: string): void {
    this.audit.push(`caller=${caller.padEnd(13)} tool=${tool.padEnd(22)} backend=${backend.padEnd(9)} decision=${decision}`);
  }

  call(req: Request): string {
    console.log(`Agent -> gateway.call(token=${req.token}, tool="${req.tool}")`);
    const identity = this.tokens.get(req.token);
    if (!identity) {
      console.log(`  [authn] token ${req.token} -> unknown -> DENY`);
      this.record('unknown', req.tool, '-', 'deny-authn');
      return this.reply('authentication failed');
    }
    console.log(`  [authn] token ${req.token} -> identity ${identity}`);

    const dot = req.tool.indexOf('.');
    const serverName = req.tool.slice(0, dot);
    const server = this.servers.get(serverName);
    if (!server) {
      console.log(`  [route] namespace '${serverName}' -> no such backend -> DENY`);
      this.record(identity, req.tool, '-', 'deny-route');
      return this.reply('unknown tool namespace');
    }
    console.log(`  [route] namespace '${serverName}' -> ${serverName} MCP server`);

    const allowed = this.allow.get(identity) || [];
    if (!allowed.includes(req.tool)) {
      console.log(`  [authz] ${identity} NOT allowed ${req.tool} -> DENY (before backend)`);
      this.record(identity, req.tool, serverName, 'deny-authz');
      return this.reply(`${req.tool} not in caller scope`);
    }
    console.log(`  [authz] ${identity} allowed ${req.tool} -> ALLOW`);

    this.used += 1;
    if (this.used > this.quota) {
      console.log(`  [policy] over ${this.quota}/min quota -> DENY (rate limit)`);
      this.record(identity, req.tool, serverName, 'deny-quota');
      return this.reply('rate limit exceeded');
    }
    console.log(`  [policy] under ${this.quota}/min quota (used ${this.used}) -> OK`);

    console.log(`  [creds] swap in scoped credential ${server.credential} (agent never sees it)`);
    const bareTool = req.tool.slice(dot + 1);
    const result = server.handle(bareTool, req.args, server.credential);
    console.log(`  [proxy] ${req.tool} -> ${result}`);
    this.record(identity, req.tool, serverName, 'allow');
    return this.reply(result);
  }

  private reply(text: string): string {
    console.log(`Agent <- ${text}\n`);
    return text;
  }

  dumpAudit(): void {
    console.log('Audit log (every call, one line):');
    for (const line of this.audit) console.log('  ' + line);
  }
}

function guardedHandler(expected: string, table: Record<string, string>): (tool: string, args: Record<string, string>, cred: string) => string {
  return (tool, _args, cred) => {
    if (cred !== expected) return 'error: bad downstream credential';
    return table[tool] || `error: ${tool} not implemented`;
  };
}

function main() {
  const gw = new Gateway();
